import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		Scanner sc=new Scanner(System.in);
		int t=sc.nextInt();
		while(t-- >0){
		    int n=sc.nextInt();
		    long res=0;
		    int[] a=new int[3*n];
		    long [] b=new long [3*n+1];
		    long[] c=new long[3*n+1];
		    for(int i=0;i<3*n;i++){
		        a[i]=sc.nextInt();
		        
		    }
		        Arrays.sort(a);
		        for(int i=1;i<=3*n;i++){
		            b[i]=a[3*n-i];
		        }
		        for(int i=1;i<=3*n;i++){
		            c[i]=c[i-1]+b[i];
		        }
		       for(int i=0;i<=n;i++){
		           int l=i,r=n-1,o=i;
		           while(l<=r){
		               int m=l+(r-l)/2;
		               long diff=b[2*m+1-i]+b[2*m+2-i]-3L*b[3*n-m-i];
		               if(diff>=0){
		                   o=m+1;
		                   l=m+1;
		               }
		               else r=m-1;
		           }
		           long s=2*c[i]+c[2*o-i]+3*c[3*n-o-i];
		           res=Math.max(res,s);
		           if(o>i){
		               long s2=2*c[i]+c[2*(o-1)-i]+3*c[3*n-(o-1)-i];
		               res=Math.max(res,s2);
		           }
		           if(o<n){
		               long s3= 2*c[i]+c[2*(o+1)-i]+3*c[3*n-(o+1)-i];
		               res=Math.max(res,s3);
		           }
		       }
		       System.out.println(res);
		}

	}
}
